import React, { useState, useEffect } from 'react';
import { Sun, Moon, Globe, Menu, X, ChevronDown, User, LogIn, UserPlus, Bell } from 'lucide-react';
import { Link, useNavigate } from 'react-router-dom';

// Traductions pour le header
const translations = {
  en: {
    home: 'Home',
    services: 'Services',
    portfolio: 'Portfolio',
    contact: 'Contact',
    language: 'Language',
    theme: 'Theme',
    light: 'Light',
    dark: 'Dark',
    system: 'System',
    welcome: 'Welcome',
    login: 'Login',
    register: 'Register',
    profile: 'Profile',
    logout: 'Logout',
    dashboard: 'Dashboard',
    getStarted: 'Get Started',
    notifications: 'Notifications',
    messages: 'Messages',
    settings: 'Settings',
  },
  fr: {
    home: 'Accueil',
    services: 'Services',
    portfolio: 'Portfolio',
    contact: 'Contact',
    language: 'Langue',
    theme: 'Thème',
    light: 'Clair',
    dark: 'Sombre',
    system: 'Système',
    welcome: 'Bienvenue',
    login: 'Connexion',
    register: 'Inscription',
    profile: 'Profil',
    logout: 'Déconnexion',
    dashboard: 'Tableau de bord',
    getStarted: 'Commencer',
    notifications: 'Notifications',
    messages: 'Messages',
    settings: 'Paramètres',
  },
  mg: {
    home: 'Fandraisana',
    services: 'Tolotra',
    portfolio: 'Portfolio',
    contact: 'Fifandraisana',
    language: 'Fiteny',
    theme: 'Teny',
    light: 'Mazava',
    dark: 'Maizina',
    system: 'Rafitra',
    welcome: 'Tonga soa',
    login: 'Hiditra',
    register: 'Hisoratra',
    profile: 'Profil',
    logout: 'Hivoaka',
    dashboard: 'Tabilao',
    getStarted: 'Atombohy',
    notifications: 'Fampahafantarana',
    messages: 'Hafatra',
    settings: 'Fanamarinana',
  },
};

const Header = ({ isAuthenticated = false, onLogout, userData = null, notificationsCount = 0 }) => {
  const navigate = useNavigate();

  // États
  const [language, setLanguage] = useState('fr');
  const [darkMode, setDarkMode] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [languageDropdownOpen, setLanguageDropdownOpen] = useState(false);
  const [themeDropdownOpen, setThemeDropdownOpen] = useState(false);
  const [userDropdownOpen, setUserDropdownOpen] = useState(false);
  const [notificationsOpen, setNotificationsOpen] = useState(false);

  // Récupérer les données utilisateur du localStorage
  const userEmail = userData?.email || localStorage.getItem('userEmail') || '';
  const userName = userData?.name || userEmail.split('@')[0] || 'User';
  const userAvatar = userData?.avatar || `https://ui-avatars.com/api/?name=${userName}&background=6366f1&color=fff`;

  // Navigation items - À PROPOS SUPPRIMÉ
  const navItems = ['home', 'services', 'portfolio', 'contact'];

  // Initialiser le mode sombre au chargement
  useEffect(() => {
    const storedTheme = localStorage.getItem('theme');
    const systemPrefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;

    if (storedTheme === 'dark' || (!storedTheme && systemPrefersDark)) {
      setDarkMode(true);
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, []);

  // Changer le mode sombre/clair
  const toggleDarkMode = () => {
    const newDarkMode = !darkMode;
    setDarkMode(newDarkMode);

    if (newDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  };

  // Changer de langue
  const changeLanguage = (lang) => {
    setLanguage(lang);
    setLanguageDropdownOpen(false);
  };

  // Changer le thème
  const changeTheme = (theme) => {
    if (theme === 'system') {
      localStorage.removeItem('theme');
      const systemPrefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
      setDarkMode(systemPrefersDark);
      if (systemPrefersDark) {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }
    } else {
      const newDarkMode = theme === 'dark';
      setDarkMode(newDarkMode);
      localStorage.setItem('theme', theme);
      if (newDarkMode) {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }
    }
    setThemeDropdownOpen(false);
  };

  // Navigation functions
  const handleLoginClick = () => {
    navigate('/login');
    setMobileMenuOpen(false);
  };

  const handleRegisterClick = () => {
    navigate('/register');
    setMobileMenuOpen(false);
  };

  const handleLogout = () => {
    if (onLogout) {
      onLogout();
    }
    setUserDropdownOpen(false);
    setMobileMenuOpen(false);
    navigate('/');
  };

  const handleDashboardClick = () => {
    navigate('/dashboard');
    setUserDropdownOpen(false);
  };

  const handleMessagesClick = () => {
    navigate('/messages');
    setUserDropdownOpen(false);
  };

  const handleSettingsClick = () => {
    navigate('/settings');
    setUserDropdownOpen(false);
  };

  // Obtenir le texte traduit
  const t = (key) => translations[language][key] || key;

  return (
    <header className="sticky top-0 z-50 w-full border-b border-neutral-200 dark:border-neutral-800 bg-white/95 dark:bg-neutral-950/95 backdrop-blur-md transition-colors duration-300 shadow-sm">
      <div className="container mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16">

          {/* Logo avec lien vers home */}
          <Link to="/" className="flex items-center space-x-2">
            <div className="h-9 w-9 rounded-lg bg-gradient-to-r from-primary-500 to-secondary-500 flex items-center justify-center shadow-md">
              <span className="font-bold text-white text-lg">N</span>
            </div>
            <span className="text-xl font-bold text-neutral-900 dark:text-white">
              Nexus<span className="text-primary-600 dark:text-primary-400">Admin</span>
            </span>
          </Link>

          {/* Navigation Desktop - À PROPOS SUPPRIMÉ */}
          <nav className="hidden md:flex items-center space-x-1">
            {navItems.map((item) => (
              <Link
                key={item}
                to={`/${item === 'home' ? '' : item}`}
                className="px-4 py-2 rounded-lg text-neutral-700 dark:text-neutral-300 hover:text-primary-600 dark:hover:text-primary-400 hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-all duration-200 font-medium text-sm"
              >
                {t(item)}
              </Link>
            ))}
          </nav>

          {/* Actions: Langue, Thème, Authentification */}
          <div className="flex items-center space-x-2">

            {/* Menu mobile burger */}
            <button
              onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
              className="md:hidden p-2 rounded-lg text-neutral-700 dark:text-neutral-300 hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors"
              aria-label="Menu"
            >
              {mobileMenuOpen ? <X size={22} /> : <Menu size={22} />}
            </button>

            {/* Notifications (uniquement si authentifié) */}
            {isAuthenticated && (
              <div className="relative">
                <button
                  onClick={() => {
                    setNotificationsOpen(!notificationsOpen);
                    setLanguageDropdownOpen(false);
                    setThemeDropdownOpen(false);
                    setUserDropdownOpen(false);
                  }}
                  className="p-2 rounded-lg text-neutral-700 dark:text-neutral-300 hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors relative"
                  aria-label={t('notifications')}
                >
                  <Bell size={20} />
                  {notificationsCount > 0 && (
                    <span className="absolute -top-1 -right-1 h-5 w-5 bg-red-500 text-white text-xs rounded-full flex items-center justify-center">
                      {notificationsCount > 9 ? '9+' : notificationsCount}
                    </span>
                  )}
                </button>

                {/* Dropdown notifications */}
                {notificationsOpen && (
                  <div className="absolute right-0 mt-2 w-80 bg-white dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 rounded-xl shadow-xl z-50 overflow-hidden">
                    <div className="p-4 border-b border-neutral-200 dark:border-neutral-800">
                      <h3 className="font-bold text-neutral-900 dark:text-white">{t('notifications')}</h3>
                    </div>
                    <div className="max-h-96 overflow-y-auto">
                      {notificationsCount === 0 ? (
                        <div className="p-8 text-center">
                          <Bell className="h-12 w-12 text-neutral-400 mx-auto mb-4" />
                          <p className="text-neutral-600 dark:text-neutral-400">Aucune notification</p>
                        </div>
                      ) : (
                        <div className="divide-y divide-neutral-200 dark:divide-neutral-800">
                          <div className="p-4 hover:bg-neutral-50 dark:hover:bg-neutral-800/50 cursor-pointer">
                            <p className="text-sm font-medium text-neutral-900 dark:text-white">Nouveau message reçu</p>
                            <p className="text-xs text-neutral-500 dark:text-neutral-500 mt-1">Il y a 5 minutes</p>
                          </div>
                          <div className="p-4 hover:bg-neutral-50 dark:hover:bg-neutral-800/50 cursor-pointer">
                            <p className="text-sm font-medium text-neutral-900 dark:text-white">Mise à jour système</p>
                            <p className="text-xs text-neutral-500 dark:text-neutral-500 mt-1">Il y a 2 heures</p>
                          </div>
                        </div>
                      )}
                    </div>
                    <div className="p-4 border-t border-neutral-200 dark:border-neutral-800">
                      <button className="w-full text-center text-sm text-primary-600 dark:text-primary-400 hover:text-primary-700 dark:hover:text-primary-300">
                        Voir toutes les notifications
                      </button>
                    </div>
                  </div>
                )}
              </div>
            )}

            {/* Sélecteur de langue */}
            <div className="relative hidden sm:block">
              <button
                onClick={() => {
                  setLanguageDropdownOpen(!languageDropdownOpen);
                  setThemeDropdownOpen(false);
                  setUserDropdownOpen(false);
                  setNotificationsOpen(false);
                }}
                className="flex items-center space-x-1 px-3 py-2 rounded-lg border border-neutral-200 dark:border-neutral-800 bg-white dark:bg-neutral-900 hover:bg-neutral-50 dark:hover:bg-neutral-800 transition-colors"
                aria-label={t('language')}
              >
                <Globe size={18} className="text-neutral-600 dark:text-neutral-400" />
                <span className="font-medium text-sm text-neutral-700 dark:text-neutral-300">
                  {language === 'en' ? 'EN' : language === 'fr' ? 'FR' : 'MG'}
                </span>
                <ChevronDown size={16} className="text-neutral-500" />
              </button>

              {/* Dropdown langue */}
              {languageDropdownOpen && (
                <div className="absolute right-0 mt-2 w-40 py-2 bg-white dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 rounded-lg shadow-lg z-50">
                  <button
                    onClick={() => changeLanguage('en')}
                    className={`w-full text-left px-4 py-2 hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors ${language === 'en' ? 'text-primary-600 dark:text-primary-400 font-medium' : 'text-neutral-700 dark:text-neutral-300'}`}
                  >
                    <div className="flex items-center space-x-2">
                      <span className="text-sm">🇺🇸</span>
                      <span className="text-sm">English</span>
                    </div>
                  </button>
                  <button
                    onClick={() => changeLanguage('fr')}
                    className={`w-full text-left px-4 py-2 hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors ${language === 'fr' ? 'text-primary-600 dark:text-primary-400 font-medium' : 'text-neutral-700 dark:text-neutral-300'}`}
                  >
                    <div className="flex items-center space-x-2">
                      <span className="text-sm">🇫🇷</span>
                      <span className="text-sm">Français</span>
                    </div>
                  </button>
                  <button
                    onClick={() => changeLanguage('mg')}
                    className={`w-full text-left px-4 py-2 hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors ${language === 'mg' ? 'text-primary-600 dark:text-primary-400 font-medium' : 'text-neutral-700 dark:text-neutral-300'}`}
                  >
                    <div className="flex items-center space-x-2">
                      <span className="text-sm">🇲🇬</span>
                      <span className="text-sm">Malagasy</span>
                    </div>
                  </button>
                </div>
              )}
            </div>

            {/* Sélecteur de thème */}
            <div className="relative hidden sm:block">
              <button
                onClick={() => {
                  setThemeDropdownOpen(!themeDropdownOpen);
                  setLanguageDropdownOpen(false);
                  setUserDropdownOpen(false);
                  setNotificationsOpen(false);
                }}
                className="flex items-center space-x-1 px-3 py-2 rounded-lg border border-neutral-200 dark:border-neutral-800 bg-white dark:bg-neutral-900 hover:bg-neutral-50 dark:hover:bg-neutral-800 transition-colors"
                aria-label={t('theme')}
              >
                {darkMode ? (
                  <Moon size={18} className="text-neutral-600 dark:text-neutral-400" />
                ) : (
                  <Sun size={18} className="text-neutral-600 dark:text-neutral-400" />
                )}
                <ChevronDown size={16} className="text-neutral-500" />
              </button>

              {/* Dropdown thème */}
              {themeDropdownOpen && (
                <div className="absolute right-0 mt-2 w-40 py-2 bg-white dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 rounded-lg shadow-lg z-50">
                  <button
                    onClick={() => changeTheme('light')}
                    className="w-full text-left px-4 py-2 flex items-center space-x-3 hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors text-neutral-700 dark:text-neutral-300"
                  >
                    <Sun size={16} />
                    <span className="text-sm">{t('light')}</span>
                  </button>
                  <button
                    onClick={() => changeTheme('dark')}
                    className="w-full text-left px-4 py-2 flex items-center space-x-3 hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors text-neutral-700 dark:text-neutral-300"
                  >
                    <Moon size={16} />
                    <span className="text-sm">{t('dark')}</span>
                  </button>
                  <button
                    onClick={() => changeTheme('system')}
                    className="w-full text-left px-4 py-2 flex items-center space-x-3 hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors text-neutral-700 dark:text-neutral-300"
                  >
                    <div className="flex items-center">
                      <Sun size={14} className="mr-[-2px]" />
                      <Moon size={14} className="ml-[-2px]" />
                    </div>
                    <span className="text-sm">{t('system')}</span>
                  </button>
                </div>
              )}
            </div>

            {/* Bouton mode sombre/clair (version simple pour mobile) */}
            <button
              onClick={toggleDarkMode}
              className="sm:hidden p-2 rounded-lg border border-neutral-200 dark:border-neutral-800 bg-white dark:bg-neutral-900 hover:bg-neutral-50 dark:hover:bg-neutral-800 transition-colors"
              aria-label={t('theme')}
            >
              {darkMode ? (
                <Moon size={20} className="text-neutral-600 dark:text-neutral-400" />
              ) : (
                <Sun size={20} className="text-neutral-600 dark:text-neutral-400" />
              )}
            </button>

            {/* Boutons d'authentification ou profil utilisateur */}
            {isAuthenticated ? (
              <div className="relative">
                <button
                  onClick={() => {
                    setUserDropdownOpen(!userDropdownOpen);
                    setLanguageDropdownOpen(false);
                    setThemeDropdownOpen(false);
                    setNotificationsOpen(false);
                  }}
                  className="flex items-center space-x-2 px-3 py-2 rounded-lg bg-gradient-to-r from-primary-500 to-secondary-500 hover:from-primary-600 hover:to-secondary-600 text-white font-medium transition-all duration-300 hover:shadow-md shadow-primary-500/20"
                >
                  <div className="h-7 w-7 rounded-full bg-white/30 flex items-center justify-center overflow-hidden">
                    <img 
                      src={userAvatar} 
                      alt={userName}
                      className="h-full w-full object-cover"
                      onError={(e) => {
                        e.target.onerror = null;
                        e.target.src = `https://ui-avatars.com/api/?name=${userName}&background=6366f1&color=fff`;
                      }}
                    />
                  </div>
                  <span className="hidden md:inline text-sm font-medium">{userName}</span>
                  <ChevronDown size={16} className="hidden md:block" />
                </button>

                {/* Dropdown utilisateur */}
                {userDropdownOpen && (
                  <div className="absolute right-0 mt-2 w-56 py-2 bg-white dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 rounded-lg shadow-lg z-50">
                    <div className="px-4 py-3 border-b border-neutral-200 dark:border-neutral-800">
                      <div className="flex items-center space-x-3">
                        <div className="h-10 w-10 rounded-full overflow-hidden">
                          <img 
                            src={userAvatar} 
                            alt={userName}
                            className="h-full w-full object-cover"
                          />
                        </div>
                        <div>
                          <p className="text-sm font-bold text-neutral-900 dark:text-white">{userName}</p>
                          <p className="text-xs text-neutral-600 dark:text-neutral-400 truncate max-w-[150px]">{userEmail}</p>
                        </div>
                      </div>
                    </div>

                    <div className="py-1">
                      <button
                        onClick={handleDashboardClick}
                        className="w-full text-left flex items-center space-x-3 px-4 py-2.5 hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors text-neutral-700 dark:text-neutral-300"
                      >
                        <div className="h-5 w-5 rounded bg-primary-500/10 flex items-center justify-center">
                          <User size={12} className="text-primary-500" />
                        </div>
                        <span className="text-sm">{t('dashboard')}</span>
                      </button>

                      <button
                        onClick={handleMessagesClick}
                        className="w-full text-left flex items-center space-x-3 px-4 py-2.5 hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors text-neutral-700 dark:text-neutral-300"
                      >
                        <div className="h-5 w-5 rounded bg-blue-500/10 flex items-center justify-center">
                          <Bell size={12} className="text-blue-500" />
                        </div>
                        <span className="text-sm">{t('messages')}</span>
                      </button>

                      <button
                        onClick={handleSettingsClick}
                        className="w-full text-left flex items-center space-x-3 px-4 py-2.5 hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors text-neutral-700 dark:text-neutral-300"
                      >
                        <div className="h-5 w-5 rounded bg-emerald-500/10 flex items-center justify-center">
                          <User size={12} className="text-emerald-500" />
                        </div>
                        <span className="text-sm">{t('settings')}</span>
                      </button>

                      <div className="px-4 py-2 border-t border-neutral-200 dark:border-neutral-800 mt-1">
                        <button
                          onClick={handleLogout}
                          className="w-full text-left flex items-center justify-center space-x-2 px-4 py-2 rounded-lg border border-red-500/30 text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 transition-colors"
                        >
                          <LogIn size={16} className="rotate-180" />
                          <span className="text-sm font-medium">{t('logout')}</span>
                        </button>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            ) : (
              <div className="hidden md:flex items-center space-x-2">
                <button
                  onClick={handleLoginClick}
                  className="flex items-center space-x-2 px-4 py-2 rounded-lg border border-neutral-300 dark:border-neutral-700 text-neutral-700 dark:text-neutral-300 hover:border-primary-500 hover:text-primary-600 dark:hover:text-primary-400 hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-all duration-300"
                >
                  <LogIn size={18} />
                  <span className="text-sm font-medium">{t('login')}</span>
                </button>
                <button
                  onClick={handleRegisterClick}
                  className="flex items-center space-x-2 px-4 py-2 rounded-lg bg-gradient-to-r from-primary-500 to-secondary-500 hover:from-primary-600 hover:to-secondary-600 text-white font-medium transition-all duration-300 hover:shadow-md shadow-primary-500/20"
                >
                  <UserPlus size={18} />
                  <span className="text-sm font-medium">{t('register')}</span>
                </button>
              </div>
            )}
          </div>
        </div>

        {/* Menu Mobile */}
        {mobileMenuOpen && (
          <div className="md:hidden py-4 border-t border-neutral-200 dark:border-neutral-800 animate-slide-up">
            <div className="flex flex-col space-y-1">
              {/* Navigation mobile - À PROPOS SUPPRIMÉ */}
              {navItems.map((item) => (
                <Link
                  key={item}
                  to={`/${item === 'home' ? '' : item}`}
                  className="px-4 py-3 rounded-lg text-neutral-700 dark:text-neutral-300 hover:text-primary-600 dark:hover:text-primary-400 hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-all duration-200 font-medium"
                  onClick={() => setMobileMenuOpen(false)}
                >
                  {t(item)}
                </Link>
              ))}

              {/* Boutons d'authentification pour mobile */}
              {!isAuthenticated ? (
                <>
                  <button
                    onClick={handleLoginClick}
                    className="flex items-center justify-center space-x-2 px-4 py-3 rounded-lg border border-neutral-300 dark:border-neutral-700 text-neutral-700 dark:text-neutral-300 hover:border-primary-500 hover:text-primary-600 dark:hover:text-primary-400 hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-all duration-300 mt-2"
                  >
                    <LogIn size={18} />
                    <span className="font-medium">{t('login')}</span>
                  </button>
                  <button
                    onClick={handleRegisterClick}
                    className="flex items-center justify-center space-x-2 px-4 py-3 rounded-lg bg-gradient-to-r from-primary-500 to-secondary-500 hover:from-primary-600 hover:to-secondary-600 text-white font-medium transition-all duration-300"
                  >
                    <UserPlus size={18} />
                    <span className="font-medium">{t('register')}</span>
                  </button>
                </>
              ) : (
                <>
                  <button
                    onClick={handleDashboardClick}
                    className="flex items-center space-x-3 px-4 py-3 rounded-lg hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors text-neutral-700 dark:text-neutral-300"
                    onClick={() => setMobileMenuOpen(false)}
                  >
                    <User size={16} />
                    <span>{t('dashboard')}</span>
                  </button>
                  <button
                    onClick={handleMessagesClick}
                    className="flex items-center space-x-3 px-4 py-3 rounded-lg hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors text-neutral-700 dark:text-neutral-300"
                    onClick={() => setMobileMenuOpen(false)}
                  >
                    <Bell size={16} />
                    <span>{t('messages')}</span>
                  </button>
                  <button
                    onClick={handleSettingsClick}
                    className="flex items-center space-x-3 px-4 py-3 rounded-lg hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors text-neutral-700 dark:text-neutral-300"
                    onClick={() => setMobileMenuOpen(false)}
                  >
                    <User size={16} />
                    <span>{t('settings')}</span>
                  </button>
                  <button
                    onClick={handleLogout}
                    className="flex items-center justify-center space-x-3 px-4 py-3 rounded-lg border border-red-500/30 text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 transition-colors mt-2"
                  >
                    <LogIn size={18} className="rotate-180" />
                    <span className="font-medium">{t('logout')}</span>
                  </button>
                </>
              )}

              {/* Sélecteur de langue mobile */}
              <div className="pt-4 mt-4 border-t border-neutral-200 dark:border-neutral-800">
                <div className="px-4 py-2 text-sm font-medium text-neutral-500 dark:text-neutral-400 mb-2">
                  {t('language')}
                </div>
                <div className="grid grid-cols-3 gap-2 px-2">
                  <button
                    onClick={() => changeLanguage('en')}
                    className={`px-3 py-2 rounded-lg text-sm ${language === 'en' ? 'bg-primary-500 text-white' : 'bg-neutral-100 dark:bg-neutral-800 text-neutral-700 dark:text-neutral-300'}`}
                  >
                    EN
                  </button>
                  <button
                    onClick={() => changeLanguage('fr')}
                    className={`px-3 py-2 rounded-lg text-sm ${language === 'fr' ? 'bg-primary-500 text-white' : 'bg-neutral-100 dark:bg-neutral-800 text-neutral-700 dark:text-neutral-300'}`}
                  >
                    FR
                  </button>
                  <button
                    onClick={() => changeLanguage('mg')}
                    className={`px-3 py-2 rounded-lg text-sm ${language === 'mg' ? 'bg-primary-500 text-white' : 'bg-neutral-100 dark:bg-neutral-800 text-neutral-700 dark:text-neutral-300'}`}
                  >
                    MG
                  </button>
                </div>
              </div>

              {/* Options de thème pour mobile */}
              <div className="pt-4 border-t border-neutral-200 dark:border-neutral-800">
                <div className="px-4 py-2 text-sm font-medium text-neutral-500 dark:text-neutral-400 mb-2">
                  {t('theme')}
                </div>
                <div className="space-y-1">
                  <button
                    onClick={() => changeTheme('light')}
                    className="flex items-center space-x-3 px-4 py-2.5 rounded-lg hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors w-full"
                  >
                    <Sun size={18} className="text-neutral-600 dark:text-neutral-400" />
                    <span className="text-neutral-700 dark:text-neutral-300">{t('light')}</span>
                  </button>
                  <button
                    onClick={() => changeTheme('dark')}
                    className="flex items-center space-x-3 px-4 py-2.5 rounded-lg hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors w-full"
                  >
                    <Moon size={18} className="text-neutral-600 dark:text-neutral-400" />
                    <span className="text-neutral-700 dark:text-neutral-300">{t('dark')}</span>
                  </button>
                  <button
                    onClick={() => changeTheme('system')}
                    className="flex items-center space-x-3 px-4 py-2.5 rounded-lg hover:bg-primary-50 dark:hover:bg-primary-900/30 transition-colors w-full"
                  >
                    <div className="flex items-center">
                      <Sun size={14} className="mr-[-2px] text-neutral-600 dark:text-neutral-400" />
                      <Moon size={14} className="ml-[-2px] text-neutral-600 dark:text-neutral-400" />
                    </div>
                    <span className="text-neutral-700 dark:text-neutral-300">{t('system')}</span>
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </header>
  );
};

export default Header;
